std::unique_ptr<CAnim>AnimCreate(const std::shared_ptr<CAnimData>&d){if(!d)throw std::invalid_argument("animation data");auto a=std::make_unique<CAnim>();a->hdata=d;a->seq.resize(d->seq.size());for(unsigned i=0;i<a->seq.size();++i)a->seq[i].elapsed=a->seq[i].scaledElapsedTime=d->seq[i].start;a->status.resize(d->obj.size());a->blendStatus.resize(d->obj.size());a->textureStatus.resize(d->tex.size());a->layerStatus.resize(d->layers.size());a->globalSeqElapsed.resize(d->globalSeqLength.size());a->lookAtTarget.resize(d->obj.size());a->cameraVisibility.assign(d->cameraObjs.size(),1.0F);a->geosetStatus.resize(d->geo.size());a->lightStatus.resize(d->obj.size());a->emitter2Status.resize(d->obj.size());a->ribbonStatus.resize(d->obj.size());return a;}void AnimResetAnimationStatus(CAnim&a){for(unsigned i=0;i<a.seq.size();++i){a.seq[i]={};if(a.hdata&&i<a.hdata->seq.size())a.seq[i].elapsed=a.seq[i].scaledElapsedTime=a.hdata->seq[i].start;}for(auto&s:a.status)s={};for(auto&s:a.blendStatus)s={};for(auto&s:a.textureStatus)s={};for(auto&s:a.layerStatus)s={};std::fill(a.cameraVisibility.begin(),a.cameraVisibility.end(),1.0F);for(auto&s:a.geosetStatus)s={};for(auto&s:a.lightStatus)s={};for(auto&s:a.emitter2Status)s={};for(auto&s:a.ribbonStatus)s={};AnimResetGlobalSequenceTimes(a);a.seqLastTime=0;}
unsigned AnimGetNumSequences(const CAnimData&d){return static_cast<unsigned>(d.seq.size());}unsigned AnimGetSequenceDuration(const CAnimData&d,unsigned s){return s<d.seq.size()?static_cast<unsigned>((std::max)(0,d.seq[s].end-d.seq[s].start)):0;}const char*AnimGetSequenceName(const CAnimData&d,unsigned s){return s<d.seq.size()?d.seq[s].name:"";}float AnimGetSequenceMoveSpeed(const CAnimData&d,unsigned s){return s<d.seq.size()?d.seq[s].moveSpeed:0;}unsigned AnimGetPrimarySequence(const CAnim&a){return a.primarySeq;}float AnimGetPrimarySequenceCompletion(const CAnim&a){if(!a.hdata||a.primarySeq>=a.seq.size())return 0;unsigned d=AnimGetSequenceDuration(*a.hdata,a.primarySeq);return d?std::clamp(float(a.seq[a.primarySeq].elapsed-a.hdata->seq[a.primarySeq].start)/d,0.0F,1.0F):0;}void AnimSetEventCallback(CAnim&a,std::function<void(const char*,const NTempest::C3Vector&)>f){a.appEvent=std::move(f);}void AnimSetSeqFinishedHandler(CAnim&a,std::function<int()>f){a.anySeqFinished=std::move(f);}
std::vector<unsigned>AnimEnumObjects(const CAnimData&d){std::vector<unsigned>r;r.reserve(d.obj.size());for(auto*o:d.obj)if(o)r.push_back(o->animObjId);return r;}
bool AnimHasObjectId(const CAnimData&d,unsigned id){return std::any_of(d.obj.begin(),d.obj.end(),[&](auto*o){return o&&o->animObjId==id;});}
bool AnimHasSequenceId(const CAnimData&d,unsigned id){return id<d.seq.size();}
unsigned AnimGetFlags(const CAnimData&d){return d.flags;}
unsigned AnimGetTotalKeys(const CAnimData&d){
    auto count=[](const auto&track){return static_cast<unsigned>(track.m_keyFrames.size());};
    unsigned total=0;
    for(auto*object:d.obj){
        if(!object)continue;
        total+=count(object->translation)+count(object->rotation)+count(object->scale);
        if(auto*light=dynamic_cast<CAnimLightObj*>(object))total+=count(light->visibility)+count(light->attenstart)+count(light->attenend)+count(light->color)+count(light->intensity)+count(light->ambColor)+count(light->ambIntensity);
        else if(auto*emitter=dynamic_cast<CAnimEmitter2Obj*>(object))total+=count(emitter->visibility)+count(emitter->particleSpeed)+count(emitter->emissionRate)+count(emitter->gravity)+count(emitter->variation)+count(emitter->latitude)+count(emitter->longitude)+count(emitter->length)+count(emitter->width)+count(emitter->zsource)+count(emitter->lifeSpan);
        else if(auto*ribbon=dynamic_cast<CAnimRibbonObj*>(object))total+=count(ribbon->visibility)+count(ribbon->heightAbove)+count(ribbon->heightBelow)+count(ribbon->color)+count(ribbon->alpha)+count(ribbon->slot);
        else if(auto*model=dynamic_cast<CAnimModelObj*>(object))total+=count(model->visibility);
        else if(auto*eventObject=dynamic_cast<CAnimEventObj*>(object))total+=count(eventObject->events);
    }
    for(const auto&geoset:d.geo)total+=count(geoset.visibility)+count(geoset.color);
    for(const auto&texture:d.tex)total+=count(texture.translation)+count(texture.rotation)+count(texture.scale);
    for(const auto&camera:d.cameraObjs)total+=count(camera.translation)+count(camera.roll)+count(camera.targetTranslation)+count(camera.visibility);
    for(const auto&layer:d.layers)total+=count(layer.visibility)+count(layer.flip);
    return total;
}
NTempest::C3Vector AnimGetObjectPosition(const CAnim&a,unsigned id){for(unsigned i=0;a.hdata&&i<a.hdata->obj.size();++i)if(a.hdata->obj[i]&&a.hdata->obj[i]->animObjId==id&&i<a.status.size()){auto&m=a.status[i].transform;return{m.d0,m.d1,m.d2};}return{};}
NTempest::C3Vector AnimGetEventObjectPosition(const CAnim&a,unsigned id){return AnimGetObjectPosition(a,id);}
bool AnimIsAttachmentEnabled(const CAnim&a,unsigned index){if(!a.hdata)return false;unsigned attachment=0;for(auto*base:a.hdata->obj)if(base&&base->type==ANIM_OBJ_ATTACHMENT){if(attachment++!=index)continue;auto*o=static_cast<CAnimModelObj*>(base);if(o->animObjId>=a.status.size()||!a.status[o->animObjId].visible)return false;return o->geosetId==0xFF||(o->geosetId<a.geosetStatus.size()&&a.geosetStatus[o->geosetId].alpha>0.0F);}return false;}
bool AnimIsCameraEnabled(const CAnim&a,unsigned index){return a.hdata&&index<a.hdata->cameraObjs.size()&&index<a.cameraVisibility.size()&&a.cameraVisibility[index]>0.0F;}
void AnimSetObjectOrdering(CAnimData&d,const std::vector<unsigned>&v){d.objectOrder=v;}void AnimResetObjectOrdering(CAnimData&d){d.objectOrder.resize(d.obj.size());for(unsigned i=0;i<d.objectOrder.size();++i)d.objectOrder[i]=i;}void AnimSetSequenceOrdering(CAnimData&d,const std::vector<unsigned>&v){d.sequenceOrder=v;}void AnimSetSequenceOrderingDefault(CAnimData&d){d.sequenceOrder.resize(d.seq.size());for(unsigned i=0;i<d.sequenceOrder.size();++i)d.sequenceOrder[i]=i;}void AnimSetCameraOrdering(CAnimData&d,const std::vector<unsigned>&v){d.cameraOrder=v;}void AnimResetCameraOrdering(CAnimData&d){d.cameraOrder.resize(d.cameraObjs.size());for(unsigned i=0;i<d.cameraOrder.size();++i)d.cameraOrder[i]=i;}
bool AnimUsesBlending(const CAnim&a){return(a.flags&1)!=0;}void AnimEnableBlending(CAnim&a,bool v){if(v)a.flags|=1;else a.flags&=~1;}void AnimLockObjectSequence(CAnim&a,unsigned o,unsigned s){if(o<a.status.size())a.status[o].lockedSequence=s;}bool AnimSetObjectTimeScale(CAnim&a,unsigned objectId,float v){if(!a.hdata)return false;for(auto*o:a.hdata->obj)if(o&&o->animObjId==objectId){if(o->splitIndex>=a.seq.size())return false;a.seq[o->splitIndex].seqTimeScale=v;return true;}return false;}float AnimGetObjectTimeScale(const CAnim&a,unsigned objectId){if(!a.hdata)return 1.0F;for(auto*o:a.hdata->obj)if(o&&o->animObjId==objectId)return o->splitIndex<a.seq.size()?a.seq[o->splitIndex].seqTimeScale:1.0F;return 1.0F;}unsigned AnimGetElapsedTime(const CAnim&a){return a.primarySeq<a.seq.size()&&a.hdata&&a.primarySeq<a.hdata->seq.size()?static_cast<unsigned>((std::max)(0,a.seq[a.primarySeq].elapsed-a.hdata->seq[a.primarySeq].start)):0;}unsigned AnimGetSequenceTime(const CAnim&a,unsigned s){return s<a.seq.size()&&a.hdata&&s<a.hdata->seq.size()?static_cast<unsigned>((std::max)(0,a.seq[s].elapsed-a.hdata->seq[s].start)):0;}void AnimForceSequenceTime(CAnim&a,unsigned s,int t){SetSequenceTime(a,s,t);}unsigned AnimGetNumSequenceFidgets(const CAnimData&d,unsigned){return static_cast<unsigned>(d.seq.size());}bool AnimSetSequenceFidget(CAnim&a,unsigned s,unsigned variation){return AnimSetSequence(a,s+variation);}bool AnimMatchSequence(CAnim&a,const CAnim&b){return AnimSetSequence(a,b.primarySeq);}
bool AnimObjectUsingLookAt(const CAnim&a,unsigned o){return o<a.status.size()&&a.status[o].lookAtId!=0xFF;}void AnimApplyObjectLookAt(CAnim&a,unsigned o,const NTempest::C3Vector&t){if(o>=a.status.size())return;if(a.lookAtTarget.size()<=o)a.lookAtTarget.resize(o+1);a.lookAtTarget[o]=t;a.status[o].lookAtId=static_cast<std::uint8_t>(o);}void AnimRemoveObjectLookAt(CAnim&a,unsigned o){if(o<a.status.size())a.status[o].lookAtId=0xFF;}bool AnimObjectUsingFaceDir(const CAnim&a,unsigned o){return o<a.status.size()&&a.status[o].faceDir;}void AnimApplyObjectFaceDir(CAnim&a,unsigned o,const NTempest::C3Vector&direction){if(o>=a.status.size())return;if(a.lookAtTarget.size()<=o)a.lookAtTarget.resize(o+1);a.lookAtTarget[o]=direction;a.status[o].faceDir=true;}void AnimRemoveObjectFaceDir(CAnim&a,unsigned o){if(o<a.status.size())a.status[o].faceDir=false;}
bool AnimEventEmitterHasKeysThisSeq(const CAnimData&d,unsigned object,unsigned seq){if(object>=d.obj.size()||!d.obj[object]||d.obj[object]->type!=ANIM_OBJ_EVENT)return false;auto&e=static_cast<CAnimEventObj&>(*d.obj[object]);return e.events.m_globalSeqId!=~0U?!e.events.m_keyFrames.empty():(seq<e.events.m_indices.size()?e.events.m_indices[seq].count!=0:!e.events.m_keyFrames.empty());}unsigned AnimGetAttachmentObjId(const CAnimData&d,unsigned index){unsigned attachment=0;for(auto*o:d.obj)if(o&&o->type==ANIM_OBJ_ATTACHMENT){if(attachment++==index)return o->animObjId;}return 0;}unsigned AnimGetAttachmentObjId(const CAnimData&d,const char*n){for(auto*o:d.obj)if(o&&o->type==ANIM_OBJ_ATTACHMENT&&_stricmp(o->name,n?n:"")==0)return o->animObjId;return~0U;}bool AnimNeedsSequenceBounds(const CAnim&a){return a.hdata&&a.hdata->seq.size()>1&&(a.hdata->flags&0x0AU)!=0;}bool AnimNeedsSequenceBounds(const CAnimData&d){return d.seq.size()>1&&(d.flags&0x0AU)!=0;}void AnimMarkFootstepSequence(CAnimData&d,unsigned s){if(s<d.seq.size())d.seq[s].flags|=0x100U;}
namespace{AnimBoneProjectCallback s_boneProject;}void AnimSetBoneProjectCallback(AnimBoneProjectCallback f){s_boneProject=std::move(f);}AnimBoneProjectCallback AnimGetBoneProjectCallback(){return s_boneProject;}
CVariations::~CVariations()=default;std::unordered_map<std::string,unsigned>HashNameList(const std::vector<std::string>&names){std::unordered_map<std::string,unsigned>out;for(unsigned i=0;i<names.size();++i){std::string key=names[i];std::transform(key.begin(),key.end(),key.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});out.try_emplace(std::move(key),i);}return out;}
bool AnimObjectUsingLookAtType(const CAnim&a,unsigned o,std::uint8_t flag){return o<a.status.size()&&(a.status[o].lookAtFlags&flag)!=0;}bool ApplyObjectLookAtType(CAnim&a,unsigned o,const NTempest::C3Vector&t,std::uint8_t flag){if(o>=a.status.size())return false;if(a.lookAtTarget.size()<=o)a.lookAtTarget.resize(o+1);a.lookAtTarget[o]=t;a.status[o].lookAtId=static_cast<std::uint8_t>(o);a.status[o].lookAtFlags|=flag;return true;}bool RemoveObjectLookAtType(CAnim&a,unsigned o,std::uint8_t flag){if(o>=a.status.size())return false;a.status[o].lookAtFlags&=static_cast<std::uint8_t>(~flag);if(!a.status[o].lookAtFlags)a.status[o].lookAtId=0xFF;return true;}
namespace{template<class T,class Name>std::vector<unsigned>OrderByName(const std::vector<std::string>&names,const std::vector<T>&items,Name name){std::vector<unsigned>out;std::vector<bool>used(items.size());for(auto&wanted:names)for(unsigned i=0;i<items.size();++i)if(!used[i]&&_stricmp(wanted.c_str(),name(items[i]))==0){out.push_back(i);used[i]=true;break;}for(unsigned i=0;i<items.size();++i)if(!used[i])out.push_back(i);return out;}std::string FirstToken(const char*name){std::string token;for(const unsigned char*c=reinterpret_cast<const unsigned char*>(name?name:"");*c&&!std::isspace(*c);++c)token.push_back(static_cast<char>(*c));return token;}}
std::vector<unsigned>SetObjectIndexOrdering(const std::vector<std::string>&n,const std::vector<CAnimObj*>&v){return OrderByName(n,v,[](CAnimObj*o){return o?o->name:"";});}std::vector<unsigned>SetCameraIndexOrdering(const std::vector<std::string>&n,const std::vector<CAnimCameraObj>&v){return OrderByName(n,v,[](const CAnimCameraObj&o){return o.name;});}std::vector<unsigned>SetSeqIndexOrdering(const std::vector<std::string>&n,const std::vector<CAnimSequence>&v){std::vector<unsigned>out(n.size(),0xFFU);for(unsigned wanted=0;wanted<n.size();++wanted)for(unsigned actual=0;actual<v.size();++actual)if(_stricmp(n[wanted].c_str(),FirstToken(v[actual].name).c_str())==0){out[wanted]=actual;break;}return out;}void SetSeqFrequencies(std::vector<CAnimSequence>&v){for(auto&s:v)if(!s.randPickChance)s.randPickChance=1;}
